CREATE DATABASE IF NOT EXISTS gk_study_helper DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE gk_study_helper;
CREATE TABLE IF NOT EXISTS knowledge_point (id BIGINT PRIMARY KEY AUTO_INCREMENT,parent_id BIGINT DEFAULT NULL,code VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,exam_type VARCHAR(32) NOT NULL,level INT NOT NULL,sort_no INT NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',importance DECIMAL(5,2) NOT NULL DEFAULT 1.00,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_kp_parent(parent_id));
CREATE TABLE IF NOT EXISTS question (id BIGINT PRIMARY KEY AUTO_INCREMENT,question_type VARCHAR(32) NOT NULL,stem TEXT NOT NULL,answer VARCHAR(500) NOT NULL,analysis TEXT,difficulty_expected DECIMAL(5,2) NOT NULL DEFAULT 50,difficulty_calibrated DECIMAL(5,2),standard_time_seconds INT NOT NULL DEFAULT 60,source_type VARCHAR(32) NOT NULL,source_year INT,source_exam VARCHAR(100),source_name VARCHAR(255),usage_type VARCHAR(32) NOT NULL DEFAULT 'TRAINING',quality_score DECIMAL(5,2),status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',version INT NOT NULL DEFAULT 1,content_hash CHAR(64),create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_question_hash(content_hash));
CREATE TABLE IF NOT EXISTS question_option (id BIGINT PRIMARY KEY AUTO_INCREMENT,question_id BIGINT NOT NULL,option_key VARCHAR(8) NOT NULL,option_text TEXT NOT NULL,sort_no INT NOT NULL,UNIQUE KEY uk_question_option(question_id,option_key));
CREATE TABLE IF NOT EXISTS question_knowledge (id BIGINT PRIMARY KEY AUTO_INCREMENT,question_id BIGINT NOT NULL,knowledge_point_id BIGINT NOT NULL,relation_type VARCHAR(20) NOT NULL,weight DECIMAL(5,2) NOT NULL DEFAULT 1,UNIQUE KEY uk_question_knowledge(question_id,knowledge_point_id));
CREATE TABLE IF NOT EXISTS media_asset (id BIGINT PRIMARY KEY AUTO_INCREMENT,storage_type VARCHAR(20) NOT NULL DEFAULT 'LOCAL',storage_path VARCHAR(500) NOT NULL,file_name VARCHAR(255) NOT NULL,file_hash CHAR(64),mime_type VARCHAR(100),file_size BIGINT,width INT,height INT,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS question_media (id BIGINT PRIMARY KEY AUTO_INCREMENT,question_id BIGINT NOT NULL,media_id BIGINT NOT NULL,role VARCHAR(20) NOT NULL,sort_no INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS answer_record (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,question_id BIGINT NOT NULL,question_version INT NOT NULL,practice_type VARCHAR(20) NOT NULL,user_answer VARCHAR(500),correct_answer_snapshot VARCHAR(500) NOT NULL,is_correct TINYINT(1) NOT NULL,duration_ms BIGINT NOT NULL,difficulty_snapshot DECIMAL(5,2) NOT NULL,knowledge_snapshot JSON NOT NULL,confidence_type VARCHAR(20) NOT NULL,error_type VARCHAR(20) NOT NULL,answer_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_answer_user_time(user_id,answer_time),INDEX idx_answer_question(question_id));
CREATE TABLE IF NOT EXISTS ability_profile (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,knowledge_point_id BIGINT NOT NULL,mastery_score DECIMAL(5,2) NOT NULL,speed_score DECIMAL(5,2) NOT NULL,stability_score DECIMAL(5,2) NOT NULL,confidence_score DECIMAL(5,2) NOT NULL,sample_count INT NOT NULL,status VARCHAR(20) NOT NULL,last_practice_time DATETIME,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_ability_user_kp(user_id,knowledge_point_id));
CREATE TABLE IF NOT EXISTS ability_history (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,knowledge_point_id BIGINT NOT NULL,mastery_score DECIMAL(5,2) NOT NULL,speed_score DECIMAL(5,2) NOT NULL,stability_score DECIMAL(5,2) NOT NULL,confidence_score DECIMAL(5,2) NOT NULL,sample_count INT NOT NULL,snapshot_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_history_user_kp(user_id,knowledge_point_id,snapshot_time));
CREATE TABLE IF NOT EXISTS learning_problem (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,problem_type VARCHAR(30) NOT NULL,knowledge_point_id BIGINT NOT NULL,title VARCHAR(200) NOT NULL,description VARCHAR(500),severity DECIMAL(5,2) NOT NULL,priority_score DECIMAL(5,2) NOT NULL,status VARCHAR(20) NOT NULL,evidence_json JSON,root_cause VARCHAR(500),discovered_time DATETIME NOT NULL,resolved_time DATETIME,validation_count INT NOT NULL DEFAULT 0,validation_pass_count INT NOT NULL DEFAULT 0,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_problem(user_id,problem_type,knowledge_point_id));
CREATE TABLE IF NOT EXISTS daily_plan (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,plan_date DATE NOT NULL,planned_minutes INT NOT NULL,actual_minutes INT NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL,generation_reason VARCHAR(500),create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_plan_user_date(user_id,plan_date));
CREATE TABLE IF NOT EXISTS daily_plan_item (id BIGINT PRIMARY KEY AUTO_INCREMENT,plan_id BIGINT NOT NULL,item_type VARCHAR(20) NOT NULL,target_type VARCHAR(30) NOT NULL,target_id BIGINT,planned_minutes INT NOT NULL,sort_no INT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_item_plan(plan_id));
